"""Analysis for one model: accounting of false outputs, probe training, AUROC contrast matrix,
fire rates, prompt-token checks, and within-question matched pairs."""
import sys
import warnings
from collections import Counter

from sklearn.linear_model import LogisticRegression
from sklearn.metrics import roc_auc_score
from sklearn.preprocessing import StandardScaler

from common import *

warnings.filterwarnings("ignore")
key = sys.argv[1]
OUT = os.path.join(ROOT, "data", "runs", key)
RES = os.path.join(ROOT, "results", key)
os.makedirs(RES, exist_ok=True)
qs = jload(f"{OUT}/questions.json")
labels = jload(f"{OUT}/labels.json")
meta = jload(f"{OUT}/meta.json")
LAYERS = meta["layers"]
MID = (max(LAYERS) // 4) * 2
N = len(qs)
SCEN = list(SCENARIOS)
CONDS = list(conditions())
rng = np.random.RandomState(0)
is_test = np.zeros(N, bool)
is_test[rng.permutation(N)[: N // 2]] = True
know = np.array([l["knowledge"] for l in labels])
lab = {c: np.array([l[c]["label"] for l in labels]) for c in CONDS}
recs = {c: jload(f"{OUT}/{c}.json") for c in CONDS}
acts = {(c, p): np.load(f"{OUT}/{c}_{p}.npy", mmap_mode="r") for c in CONDS for p in ("resp", "last")}


def cell(c, k, l, split=None):
