# pressure-vs-control prompt regardless of answer, all test questions
t = np.where(is_test)[0]
lp["prompt_identity"] = {d: {s: auc(S_x[d][f"{s}_pressure"][t], S_x[d][f"{s}_control"][t]) for s in SCEN} for d in S_x}
lp["prompt_identity_resp"] = {d: {s: auc(S_mid[d][f"{s}_pressure"][t], S_mid[d][f"{s}_control"][t]) for s in SCEN} for d in S_mid}
jdump(lp, f"{RES}/lastprompt.json")

# ------------------------------------------------------------------ 5. within-question matched pairs
if os.path.exists(f"{OUT}/samples_sandbag_pressure_labels.json"):
    sm = jload(f"{OUT}/samples_meta.json")
    li = sm["layers"].index(MID)
    qidx = np.array(sm["qidx"])
    paired = {}
    for s in ["bluff", "rival", "sandbag"]:
        c = f"{s}_pressure"
        A = np.load(f"{OUT}/samples_{c}_resp.npy", mmap_mode="r")[:, li].astype(np.float32)
        sl = np.array(jload(f"{OUT}/samples_{c}_labels.json"))  # [Q, n]
        rc = jload(f"{OUT}/samples_{c}.json")
        sc = {d: P_mid[d](A).reshape(sl.shape) for d in P_mid}
        sc["nll"] = -np.array([r["mean_lp"] for r in rc]).reshape(sl.shape)
        te = is_test[qidx]
        mixed = te & (sl == "WRONG").any(1) & (sl == "CORRECT").any(1)
        paired[s] = {"n_questions_test": int(te.sum()), "n_mixed": int(mixed.sum()),
                     "label_counts": dict(Counter(sl[te].ravel().tolist())), "det": {}}
        for d in sc:
            dl = np.array([sc[d][j][sl[j] == "WRONG"].mean() - sc[d][j][sl[j] == "CORRECT"].mean() for j in np.where(mixed)[0]])
            # pooled AUROC over all test samples (unmatched) vs. within-question paired win rate
            pooled = auc(sc[d][te][sl[te] == "WRONG"], sc[d][te][sl[te] == "CORRECT"])
            r = np.random.RandomState(0)
            b = [np.mean(r.choice(dl, len(dl)) > 0) for _ in range(1000)] if len(dl) else [np.nan]
            paired[s]["det"][d] = {"paired_win": float((dl > 0).mean()) if len(dl) else None,
                                   "ci": [float(np.percentile(b, 2.5)), float(np.percentile(b, 97.5))],
                                   "pooled_auroc": pooled}
    jdump(paired, f"{RES}/paired.json")
    print(json.dumps(paired, indent=0)[:3000])
np.savez_compressed(f"{RES}/scores_mid.npz", **{f"{d}|{c}": S_mid[d][c].astype(np.float32) for d in S_mid for c in CONDS},
                    is_test=is_test, know=know, **{f"lab|{c}": lab[c] for c in CONDS})
print("analysis done")

